create function public.crm_update_staff(p_user uuid,p_name text,p_permissions jsonb) returns void language plpgsql security definer set search_path='' as $$ declare p uuid; old jsonb;begin
 if not public.is_admin() then raise exception 'Apenas a administradora pode gerenciar a equipe' using errcode='42501';end if;
 if length(trim(p_name))<2 or length(p_name)>150 or jsonb_typeof(p_permissions)<>'object' or exists(select 1 from jsonb_each(p_permissions) where key not in ('enabled','view_crm','manage_clients','manage_enrollments','complete_contacts','edit_observations','view_tasks','complete_tasks','view_contact','schedule_appointments') or jsonb_typeof(value)<>'boolean') then raise exception 'Revise nome e permissões';end if;
 select id into p from public.profiles where user_id=p_user and role='secretary' for update;if p is null then raise exception 'Funcionária não encontrada';end if;
 select to_jsonb(s) into old from public.staff_permissions s where user_id=p_user;
 update public.profiles set full_name=trim(p_name) where id=p;
 insert into public.staff_permissions(user_id,enabled,view_crm,manage_clients,manage_enrollments,complete_contacts,edit_observations,view_tasks,complete_tasks,view_contact,schedule_appointments)
 values(p_user,coalesce((p_permissions->>'enabled')::boolean,false),coalesce((p_permissions->>'view_crm')::boolean,false),coalesce((p_permissions->>'manage_clients')::boolean,false),coalesce((p_permissions->>'manage_enrollments')::boolean,false),coalesce((p_permissions->>'complete_contacts')::boolean,false),coalesce((p_permissions->>'edit_observations')::boolean,false),coalesce((p_permissions->>'view_tasks')::boolean,false),coalesce((p_permissions->>'complete_tasks')::boolean,false),coalesce((p_permissions->>'view_contact')::boolean,false),coalesce((p_permissions->>'schedule_appointments')::boolean,false))
 on conflict(user_id) do update set enabled=excluded.enabled,view_crm=excluded.view_crm,manage_clients=excluded.manage_clients,manage_enrollments=excluded.manage_enrollments,complete_contacts=excluded.complete_contacts,edit_observations=excluded.edit_observations,view_tasks=excluded.view_tasks,complete_tasks=excluded.complete_tasks,view_contact=excluded.view_contact,schedule_appointments=excluded.schedule_appointments;
 insert into public.crm_audit(actor_id,action,before_data,after_data) values(public.current_profile_id(),'staff_updated',old,jsonb_build_object('staff_id',p,'name',p_name,'permissions',p_permissions));end $$;
revoke all on function public.crm_update_staff(uuid,text,jsonb) from public,anon;
grant execute on function public.crm_update_staff(uuid,text,jsonb) to authenticated;
